\begin{definition}[Pointwise resolvent order]\label{def:order}
For maximal operators of a fixed orientation, define the \emph{pointwise resolvent order} by
\begin{equation}\label{eq:order}
 f\leq g\quad\Longleftrightarrow\quad
 \begin{cases}
 J_f\geq J_g&\text{on }\Mu,\\
 J_f\leq J_g&\text{on }\Md.
 \end{cases}
\end{equation}
All comparisons of functions in this definition are pointwise on $\R$.
\end{definition}
Injectivity of the resolvent representation makes the pointwise resolvent order a partial order on each class. There is no single order on their union with both conventions: for the vertical operators $N_{\{a\}}$ with graphs $\{a\}\times\R$, one has $N_{\{a\}}\leq N_{\{b\}}$ exactly when $a\geq b$ in $\Mu$, and when $a\leq b$ in $\Md$.

\begin{definition}[Order on intervals]\label{def:intervalorder}
Using the upward and downward hulls defined in~\eqref{eq:hull_p_m}, for nonempty intervals $I,J\subset\R$, define
\begin{equation}\label{eq:intervalorder}
 I\leq J\quad\Longleftrightarrow\quad
 I_+\supseteq J_+\ \text{and}\ I_-\subseteq J_-.
\end{equation}
\end{definition}
On nonempty intervals this is the Egli--Milner order
\cite[Section~3.3]{KeimelPlotkin2017}. It is a partial order, since
$I=I_+\cap I_-$. For closed bounded intervals, $[a,b]\leq[c,d]$ is equivalent to $a\leq c$ and $b\leq d$. The hull formulation also retains endpoint inclusion: for example, $[0,1)\leq(0,1]$, whereas $(0,1)$ and $[0,1]$ are incomparable.

\begin{example}[Power tails]
If, for some $A,\alpha>0$, $q_\Delta(u)\leq Au^{-\alpha}$, then
\begin{equation}\label{eq:local-network-power}
 \begin{aligned}
 \TT[|V-m_V|](u)
 &\leq DAe^{\alpha L}(6/u)^\alpha\\
 &\quad{}\times
 \prod_{\ell=1}^L\left(
 \max\{m_x,m_\ell\}
 +\frac{A(12/u)^\alpha}
        {\sqrt{\min\{Np_0,p_\ell+p_{\ell-1}\}}}
 \right).
 \end{aligned}
\end{equation}
This follows by using, for $m,c\geq0$,
$\mathcal G(m+c\,\id^{-\alpha})(v)
 \leq e^\alpha(m+cv^{-\alpha})$.
The far-tail quantile power is $\alpha(L+1)$.
The hypothesis concerns the joint law, not merely marginal
entrywise tails.
\end{example}

\begin{definition}[Infimum and supremum of intervals]\label{def:intervalextrema}
Using the notation of Definition~\ref{def:intervalorder}, for a finite nonempty family $(I_a)_{a\in A}$ of nonempty intervals define
\begin{align*}
 \inf_{a\in A}\{I_a\}
   &=\left(\bigcup_{a\in A}(I_a)_+\right)
     \cap\left(\bigcap_{a\in A}(I_a)_-\right),
     \\
 \sup_{a\in A}\{I_a\}&=\left(\bigcup_{a\in A}(I_a)_-\right)
     \cap\left(\bigcap_{a\in A}(I_a)_+\right).
\end{align*}
These intervals are the greatest lower bound and least upper bound, respectively, in the interval order; they need not be members of the original family. Consequently, for nonempty intervals $I,J$,
\begin{equation}\label{eq:intervalorderextrema}
 I\leq J\quad\Longleftrightarrow\quad
 \inf\{I,J\}=I\quad\Longleftrightarrow\quad\sup\{I,J\}=J.
\end{equation}
\end{definition}
For a single interval $I$, $\inf I$ and $\sup I$ denote its scalar endpoints in the extended real line.
The definitions give the hull identities
\begin{align*}
 (\inf_a\{I_a\})_+&=\bigcup_a(I_a)_+,&
 (\inf_a\{I_a\})_-&=\bigcap_a(I_a)_-,\\
 (\sup_a\{I_a\})_+&=\bigcap_a(I_a)_+,&
 (\sup_a\{I_a\})_-&=\bigcup_a(I_a)_-.
\end{align*}
The greatest-lower-bound and least-upper-bound properties now follow directly from \eqref{eq:intervalorder}.
